import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;

import 'package:tako_den/src/content_type.dart';

String generateWebAssets({String directory = 'web'}) {
  final files =
      Directory(directory)
          .listSync(recursive: true, followLinks: false)
          .whereType<File>()
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));
  String quote(String value) =>
      "'${value.replaceAll(r'\', r'\\').replaceAll("'", r"\'").replaceAll(r'$', r'\$')}'";
  final out = StringBuffer(
    '// Generated by tool/embed_web.dart. Do not edit.\n// dart format off\n',
  );
  out.writeln(
    'const webAssets = <String, ({String contentType, String bytes})>{',
  );
  for (final file in files) {
    final path = p.relative(file.path, from: directory).replaceAll(r'\', '/');
    out.writeln(
      '  ${quote(path)}: (contentType: ${quote(contentType(path))}, bytes: ${quote(base64.encode(file.readAsBytesSync()))}),',
    );
  }
  out.writeln('};\n// dart format on');
  return out.toString();
}

void main() {
  File('lib/src/web_assets.g.dart').writeAsStringSync(generateWebAssets());
}
